 {route.startsWith('chat/')&&(chat?.status==='accepted'&&canConnect&&chat.available!==false?<Conversation accountId={accountId} me={me} key={chat.id} connection={chat} onManagePhoto={()=>nav('My profile')} api={api} onProfile={()=>nav('person/'+encodeURIComponent(chat.person.id))} onBack={()=>nav('Connections')} onReport={startReport} onRead={()=>load()} onCircle={()=>circleWith(chat)} onPhoto={()=>act({action:'photo_consent',connection:chat.id,share:!chat.photoMine},chat.photoMine?'Photo sharing stopped.':'Photo exchange requested. Both people must agree.')} onBlock={async()=>{if(await act({action:'block',target:chat.person.id},'Member blocked.'))nav('Connections');}} onClose={()=>setCloseTarget(chat)}/>:<div className="empty-state"><h2>Conversation unavailable.</h2><p>Your profile and the other member’s profile must be active and admitted.</p>{chat&&<div className="inline-actions"><button className="muted-button" onClick={()=>startReport(chat.person)}>Report</button><button className="muted-button" disabled={busy} onClick={async()=>{if(await act({action:'block',target:chat.person.id},'Member blocked.'))nav('Connections');}}>Block</button><button className="muted-button" disabled={busy} onClick={()=>setCloseTarget(chat)}>End connection</button></div>}<button className="primary" onClick={()=>nav('Connections')}>Back to conversations</button></div>)}
 {route.startsWith('circles')&&<><div className="section-tabs"><button onClick={()=>nav('Discover')}>People</button><button className="active" aria-pressed="true">Circles</button><button onClick={()=>nav('Saved')}>Saved</button></div><Circles key={accountId+':'+canConnect} accountId={accountId} connections={connections} active={canConnect} onReport={startReport} initialConnection={seedConnection} initialCircle={route.startsWith('circles/')&&route!=='circles/requests'?decodeURIComponent(route.slice(8)):''} initialSection={route==='circles/requests'?'Requests':'Discover'}/></>}
